  "code": "import pandas as pd; df = pd.read_csv('/data/Crime_records.csv'); df['Date_Reported'] = pd.to_datetime(df['Date_Reported']); fraud_data = df[(df['Crime_Type'] == 'Fraud') & (df['Date_Reported'] >= '2014-05-01') & (df['Date_Reported'] <= '2021-05-31')]; avg_suspect_age = fraud_data['Suspect_Age'].mean(); avg_victim_age = fraud_data['Victim_Age'].mean(); percent_online_frauds = (fraud_data[fraud_data['Location'] == 'Online'].shape[0] / fraud_data.shape[0]) * 100; print(f\"Average suspect age: {avg_suspect_age:.2f}, Average victim age: {avg_victim_age:.2f}, Percentage of online frauds: {percent_online_frauds:.2f}%\")"
}
